begin
    if to_regclass('public.holds') is not null and to_regclass('public.patrons') is not null then
        if not exists (
            select 1 from pg_constraint c
            where c.conrelid = 'public.holds'::regclass and c.contype = 'f'
              and pg_get_constraintdef(c.oid) like 'FOREIGN KEY (patron_id)%'
